#!/bin/sh
# Lucky Pit build: compiles for CLDC 1.1 / MIDP 2.0 with preverification
# (StackMap attributes generated by ECJ -target cldc1.1), packs the JAR and
# writes a JAD whose MIDlet-Jar-Size matches the JAR byte-for-byte.
#   ./build.sh            build from committed resources
#   ./build.sh --assets   regenerate all PNG/WAV/MIDI/card data first (needs Python 3 + Pillow)
set -e
cd "$(dirname "$0")"
VERSION=1.0.0
LIB=lib
MAVEN=https://repo1.maven.org/maven2

fetch() {
    if [ ! -f "$LIB/$2" ]; then
        echo "download $2"
        mkdir -p "$LIB"
        n=0
        until curl -fsSL -o "$LIB/$2" "$MAVEN/$1"; do
            n=$((n + 1))
            [ $n -ge 5 ] && { echo "cannot download $1"; exit 1; }
            sleep $((n * 5))
        done
    fi
}
# API stubs (MicroEmulator project) and the Eclipse compiler
fetch org/microemu/cldcapi11/2.0.4/cldcapi11-2.0.4.jar cldcapi11.jar
fetch org/microemu/midpapi20/2.0.4/midpapi20-2.0.4.jar midpapi20.jar
fetch org/eclipse/jdt/core/compiler/ecj/4.6.1/ecj-4.6.1.jar ecj.jar

DEBUG=false
for arg in "$@"; do
    case "$arg" in
        --assets) python3 tools/build_assets.py ;;
        --debug) DEBUG=true ;;
    esac
done

rm -rf build
mkdir -p build/classes build/jar build/gen/luckypit dist
cat > build/gen/luckypit/BuildConfig.java <<BC
package luckypit;

/** Generated by build.sh. DEBUG builds log to the console and enable test cheats. */
public interface BuildConfig {
    boolean DEBUG = $DEBUG;
    String VERSION = "$VERSION";
}
BC

echo "check that every in-game character exists in the pixel font"
python3 tools/check_glyphs.py

echo "compile (CLDC 1.1, MIDP 2.0, preverified)"
java -jar $LIB/ecj.jar -source 1.3 -target cldc1.1 -nowarn -encoding UTF-8 -g:none \
    -bootclasspath "$LIB/cldcapi11.jar:$LIB/midpapi20.jar" \
    -d build/classes src build/gen

cp -r build/classes/. build/jar/
cp -r res/. build/jar/

cat > build/MANIFEST.MF <<MF
MIDlet-1: Lucky Pit,/icon.png,luckypit.LuckyPitMIDlet
MIDlet-Name: Lucky Pit
MIDlet-Vendor: Lucky Pit Team
MIDlet-Version: $VERSION
MIDlet-Description: Roguelike slot machine. Virtual coins only.
MIDlet-Icon: /icon.png
MicroEdition-Profile: MIDP-2.0
MicroEdition-Configuration: CLDC-1.1
Nokia-MIDlet-Category: Game
MF

rm -f build/LuckyPit.jar
(cd build/jar && jar cfm ../LuckyPit.jar ../MANIFEST.MF .)

SIZE=$(wc -c < build/LuckyPit.jar | tr -d ' ')
cat > build/LuckyPit.jad <<JAD
MIDlet-1: Lucky Pit,/icon.png,luckypit.LuckyPitMIDlet
MIDlet-Name: Lucky Pit
MIDlet-Vendor: Lucky Pit Team
MIDlet-Version: $VERSION
MIDlet-Description: Roguelike slot machine. Virtual coins only.
MIDlet-Icon: /icon.png
MIDlet-Jar-URL: LuckyPit.jar
MIDlet-Jar-Size: $SIZE
MicroEdition-Profile: MIDP-2.0
MicroEdition-Configuration: CLDC-1.1
Nokia-MIDlet-Category: Game
JAD

if [ "$DEBUG" = "true" ]; then
    mkdir -p dist/debug
    cp build/LuckyPit.jar build/LuckyPit.jad dist/debug/
else
    cp build/LuckyPit.jar build/LuckyPit.jad dist/
fi
echo "verify class files"
python3 tools/verify_classes.py build/classes "$LIB/cldcapi11.jar" "$LIB/midpapi20.jar"
echo "OK: LuckyPit.jar ($SIZE bytes) debug=$DEBUG"
